<?php defined('SYSPATH') or die('No direct script access.');
/** Lot/serial identity, WMS allocations and directed production genealogy. */
class Service_Erp412_Traceability
{
 protected static $_instance;public static function instance(){return self::$_instance?:(self::$_instance=new self);}protected function __construct(){}
 public function create_lot(array $data,$actor=NULL)
 {
  $item=(int)Arr::get($data,'item_id');if($item<1 OR !DB::select('id')->from('erp_227_objects')->where('id','=',$item)->execute()->current())throw new Kohana_Exception('Выберите существующую номенклатуру');
  $mode=(string)Arr::get($data,'tracking_mode','lot');$serial=trim((string)Arr::get($data,'serial_number'));if($mode==='serial'&&$serial==='')throw new Kohana_Exception('Для serial обязателен серийный номер');
  $number=trim((string)Arr::get($data,'lot_number'));if($number==='')$number=$this->number();
  $row=DB::query(Database::SELECT,"INSERT INTO erp_412_lots(item_id,lot_number,serial_number,tracking_mode,status,source_type,source_id,supplier_id,manufactured_at,expires_at,metadata,created_by)
   VALUES(:item,:number,:serial,:mode,:status,:source,:source_id,:supplier,:manufactured,:expires,cast(:metadata AS jsonb),:actor) RETURNING *")
   ->parameters(array(':item'=>$item,':number'=>$number,':serial'=>$serial?:NULL,':mode'=>$mode,':status'=>Arr::get($data,'status','available'),':source'=>Arr::get($data,'source_type'),':source_id'=>Arr::get($data,'source_id')?:NULL,':supplier'=>Arr::get($data,'supplier_id')?:NULL,':manufactured'=>Arr::get($data,'manufactured_at')?:NULL,':expires'=>Arr::get($data,'expires_at')?:NULL,':metadata'=>json_encode((array)Arr::get($data,'metadata',array()),JSON_UNESCAPED_UNICODE),':actor'=>$actor?:NULL))->execute()->current();
  $this->event($row['id'],'created',NULL,$row['status'],Arr::get($data,'reason'),$row['source_type'],$row['source_id'],$actor);$this->fact('erp412.lot.created',$row,$actor);return $this->get($row['id']);
 }
 public function from_movement($movement_id,array $data=array(),$actor=NULL)
 {
  $m=$this->movement($movement_id);if($m['type']!=='receipt')throw new Kohana_Exception('Автосоздание партии возможно только для прихода');
  $existing=DB::select('id')->from('erp_412_lots')->where('source_type','=','erp401_movement')->where('source_id','=',(int)$movement_id)->execute()->get('id');if($existing)return $this->get($existing);
  $db=Database::instance();$db->begin();try{DB::query(Database::SELECT,'SELECT pg_advisory_xact_lock(:id)')->param(':id',(int)$movement_id)->execute();$again=DB::select('id')->from('erp_412_lots')->where('source_type','=','erp401_movement')->where('source_id','=',(int)$movement_id)->execute()->get('id');if($again){$db->commit();return $this->get($again);}$lot=$this->create_lot($data+array('item_id'=>(int)$m['item_id'],'source_type'=>'erp401_movement','source_id'=>(int)$movement_id),$actor);$this->allocate_locked($lot['id'],$movement_id,'receipt',(float)$m['qty'],(int)$m['warehouse_id'],$actor);$this->auto_quality_links($lot,$m,$actor);$db->commit();return $this->get($lot['id']);}catch(Throwable $e){$db->rollback();throw $e;}
 }
 public function allocate($lot_id,$movement_id,$direction,$qty,$warehouse_id=NULL,$actor=NULL)
 {
  $db=Database::instance();$db->begin();try{DB::query(Database::SELECT,'SELECT pg_advisory_xact_lock(:id)')->param(':id',(int)$movement_id)->execute();$r=$this->allocate_locked($lot_id,$movement_id,$direction,$qty,$warehouse_id,$actor);$db->commit();return $r;}catch(Throwable $e){$db->rollback();throw $e;}
 }
 protected function allocate_locked($lot_id,$movement_id,$direction,$qty,$warehouse_id=NULL,$actor=NULL)
 {
  $lot=$this->get($lot_id);$m=$this->movement($movement_id);$direction=(string)$direction;$qty=round(Erp::num($qty),6);if($qty<=0)throw new Kohana_Exception('Количество allocation должно быть больше нуля');if((int)$lot['item_id']!==(int)$m['item_id'])throw new Kohana_Exception('Номенклатура партии не совпадает с движением');
  $allowed=array('receipt'=>array('receipt'),'issue'=>array('issue'),'transfer'=>array('transfer_out','transfer_in'),'adjust'=>array('adjust_in','adjust_out'));if(!isset($allowed[$m['type']]) OR !in_array($direction,$allowed[$m['type']],TRUE))throw new Kohana_Exception('Направление allocation не соответствует движению WMS');
  if($lot['tracking_mode']==='serial'&&abs($qty-1)>0.000001)throw new Kohana_Exception('Serial allocation должен иметь количество 1');
  if(in_array($direction,array('issue','transfer_out','adjust_out'),TRUE)&&in_array($lot['status'],array('quarantine','recalled','scrapped','consumed'),TRUE))throw new Kohana_Exception('Партия заблокирована для расхода: '.$lot['status']);
  $warehouse=$warehouse_id?:($direction==='transfer_in'?(int)$m['warehouse_to_id']:(int)$m['warehouse_id']);if($warehouse<1)throw new Kohana_Exception('Не указан склад allocation');
  if(in_array($direction,array('issue','transfer_out','adjust_out'),TRUE)){$available=(float)DB::query(Database::SELECT,"SELECT coalesce(sum(CASE WHEN direction IN('receipt','transfer_in','adjust_in') THEN qty ELSE -qty END),0) qty FROM erp_412_allocations WHERE lot_id=:lot AND warehouse_id=:warehouse")->parameters(array(':lot'=>(int)$lot['id'],':warehouse'=>$warehouse))->execute()->get('qty');if($available+0.000001<$qty)throw new Kohana_Exception('Недостаточно количества этой партии на выбранном складе');}
  $used=(float)DB::select(array(DB::expr('coalesce(sum(qty),0)'),'qty'))->from('erp_412_allocations')->where('movement_id','=',(int)$movement_id)->where('direction','=',$direction)->execute()->get('qty');if($used+$qty>(float)$m['qty']+0.000001)throw new Kohana_Exception('Сумма allocations превышает количество движения WMS');
  $id=DB::insert('erp_412_allocations',array('lot_id','movement_id','direction','warehouse_id','qty','created_by'))->values(array((int)$lot['id'],(int)$movement_id,$direction,$warehouse,$qty,$actor?:NULL))->execute()[0];
  $this->event($lot['id'],'allocated',$lot['status'],$lot['status'],$direction.' '.$qty,'erp401_movement',$movement_id,$actor);return array('id'=>(int)$id,'lot'=>$this->get($lot['id']));
 }
 public function allocate_transfer($lot_id,$movement_id,$qty,$actor=NULL)
 {
  $m=$this->movement($movement_id);if($m['type']!=='transfer')throw new Kohana_Exception('Требуется движение transfer');$db=Database::instance();$db->begin();try{DB::query(Database::SELECT,'SELECT pg_advisory_xact_lock(:id)')->param(':id',(int)$movement_id)->execute();$this->allocate_locked($lot_id,$movement_id,'transfer_out',$qty,(int)$m['warehouse_id'],$actor);$r=$this->allocate_locked($lot_id,$movement_id,'transfer_in',$qty,(int)$m['warehouse_to_id'],$actor);$db->commit();return $r;}catch(Throwable $e){$db->rollback();throw $e;}
 }
 public function link(array $data,$actor=NULL)
 {
  $db=Database::instance();$db->begin();try{DB::query(Database::SELECT,'SELECT pg_advisory_xact_lock(412)')->execute();$result=$this->link_locked($data,$actor);$db->commit();return $result;}catch(Throwable $e){$db->rollback();throw $e;}
 }
 protected function link_locked(array $data,$actor=NULL)
 {
  $input=$this->get(Arr::get($data,'input_lot_id'));$output=$this->get(Arr::get($data,'output_lot_id'));if($input['id']===$output['id'])throw new Kohana_Exception('Партия не может происходить сама из себя');if($this->reachable($output['id'],$input['id']))throw new Kohana_Exception('Связь создаёт цикл genealogy');
  $qty=round(Erp::num(Arr::get($data,'qty_input')),6);if($qty<=0)throw new Kohana_Exception('Укажите расход входной партии');$id=DB::insert('erp_412_genealogy',array('input_lot_id','output_lot_id','relation','order_id','operation_id','qty_input','qty_output','uom_code','created_by'))->values(array((int)$input['id'],(int)$output['id'],Arr::get($data,'relation','consume'),Arr::get($data,'order_id')?:NULL,Arr::get($data,'operation_id')?:NULL,$qty,Arr::get($data,'qty_output')?:NULL,Arr::get($data,'uom_code','pcs'),$actor?:NULL))->execute()[0];
  $this->event($input['id'],'consumed_into',$input['status'],$input['status'],'→ '.$output['lot_number'],'genealogy',$id,$actor);$this->fact('erp412.genealogy.linked',$output,$actor,array('input_lot_uuid'=>$input['uuid'],'edge_id'=>(int)$id));return array('id'=>(int)$id,'input'=>$input,'output'=>$output);
 }
 public function record_production($input_lot_id,$output_lot_id,$order_id,$qty,$actor=NULL)
 {
  $db=Database::instance();$db->begin();try{
   // One atomic unit: WMS allocations and genealogy either both persist or both roll back.
   // The module lock serialises replay/cycle checks; movement locks protect capacities.
   DB::query(Database::SELECT,'SELECT pg_advisory_xact_lock(412)')->execute();
   $input=$this->get($input_lot_id);$output=$this->get($output_lot_id);$order=DB::select()->from('erp_402_orders')->where('id','=',(int)$order_id)->execute()->current();if(!$order)throw new Kohana_Exception('Производственный заказ не найден');if((int)$order['item_id']!==(int)$output['item_id'])throw new Kohana_Exception('Выходная партия не соответствует изделию заказа');
   $source=DB::query(Database::SELECT,"SELECT m.* FROM erp_412_lots l JOIN erp_401_movements m ON m.id=l.source_id WHERE l.id=:lot AND l.source_type='erp401_movement' AND m.type='receipt' AND m.status='posted' AND m.doc_type='erp402_order' AND m.doc_id=:order")->parameters(array(':lot'=>(int)$output['id'],':order'=>(int)$order_id))->execute()->current();if(!$source)throw new Kohana_Exception('Выходная партия не подтверждена проведённым выпуском WMS по этому заказу');
   $qty=round(Erp::num($qty),6);if($qty<=0)throw new Kohana_Exception('Укажите фактический расход партии');$line=DB::query(Database::SELECT,"SELECT sum(qty_issued) qty_issued,min(uom_code) uom_code FROM erp_402_order_items WHERE order_id=:order AND item_id=:item HAVING sum(qty_issued)>0")->parameters(array(':order'=>(int)$order_id,':item'=>(int)$input['item_id']))->execute()->current();if(!$line OR (float)$line['qty_issued']+0.000001<$qty)throw new Kohana_Exception('Материал или количество не подтверждены списанием заказа');
   $edge=DB::select()->from('erp_412_genealogy')->where('input_lot_id','=',(int)$input['id'])->where('output_lot_id','=',(int)$output['id'])->where('order_id','=',(int)$order_id)->execute()->current();if($edge){if(abs((float)$edge['qty_input']-$qty)>0.000001)throw new Kohana_Exception('Связь уже записана с другим количеством');$db->commit();return array('id'=>(int)$edge['id'],'input'=>$input,'output'=>$output,'replayed'=>TRUE);}
   $movement_ids=DB::select('id')->from('erp_401_movements')->where('type','=','issue')->where('status','=','posted')->where('doc_type','=','erp402_order')->where('doc_id','=',(int)$order_id)->where('item_id','=',(int)$input['item_id'])->order_by('id','ASC')->execute()->as_array(NULL,'id');if(!$movement_ids)throw new Kohana_Exception('Не найдены движения списания материала по заказу');foreach($movement_ids as $movement_id)DB::query(Database::SELECT,'SELECT pg_advisory_xact_lock(:id)')->param(':id',(int)$movement_id)->execute();
   $movements=DB::query(Database::SELECT,"SELECT m.*,coalesce((SELECT sum(a.qty) FROM erp_412_allocations a WHERE a.movement_id=m.id AND a.direction='issue'),0) allocated,coalesce((SELECT sum(a.qty) FROM erp_412_allocations a WHERE a.movement_id=m.id AND a.direction='issue' AND a.lot_id=:lot),0) lot_allocated FROM erp_401_movements m WHERE m.type='issue' AND m.status='posted' AND m.doc_type='erp402_order' AND m.doc_id=:order AND m.item_id=:item ORDER BY m.id")->parameters(array(':lot'=>(int)$input['id'],':order'=>(int)$order_id,':item'=>(int)$input['item_id']))->execute()->as_array();
   $already=0.0;$capacity=0.0;foreach($movements as $m){$already+=(float)$m['lot_allocated'];$capacity+=max(0,(float)$m['qty']-(float)$m['allocated']);}$remaining=$qty-$already;if($remaining<-0.000001)throw new Kohana_Exception('По движениям уже распределено больше указанного расхода');if($remaining>$capacity+0.000001)throw new Kohana_Exception('Недостаточно нераспределённого списания WMS по заказу');
   foreach($movements as $m){if($remaining<=0.000001)break;$take=min($remaining,max(0,(float)$m['qty']-(float)$m['allocated']));if($take>0){$this->allocate_locked($input['id'],$m['id'],'issue',$take,(int)$m['warehouse_id'],$actor);$remaining-=$take;}}
   $result=$this->link_locked(array('input_lot_id'=>$input['id'],'output_lot_id'=>$output['id'],'relation'=>'consume','order_id'=>(int)$order_id,'qty_input'=>$qty,'uom_code'=>$line['uom_code']),$actor);$result['replayed']=FALSE;$db->commit();return $result;
  }catch(Throwable $e){$db->rollback();throw $e;}
 }
 public function link_inspection($lot_id,$inspection_id,$actor=NULL)
 {
  $lot=$this->get($lot_id);$i=DB::select()->from('erp_405_inspections')->where('id','=',(int)$inspection_id)->execute()->current();if(!$i)throw new Kohana_Exception('Контроль качества не найден');if((int)$i['item_id']!==(int)$lot['item_id'])throw new Kohana_Exception('Номенклатура контроля и партии не совпадает');DB::query(Database::INSERT,'INSERT INTO erp_412_quality_links(lot_id,inspection_id) VALUES(:lot,:inspection) ON CONFLICT DO NOTHING')->parameters(array(':lot'=>(int)$lot['id'],':inspection'=>(int)$inspection_id))->execute();$this->event($lot['id'],'quality_linked',$lot['status'],$lot['status'],$i['number'],'erp405_inspection',$inspection_id,$actor);return $this->get($lot['id']);
 }
 public function transition($lot_id,$status,$reason,$actor=NULL,$reference_type=NULL,$reference_id=NULL)
 {
  $lot=$this->get($lot_id);$status=(string)$status;$allowed=array('available'=>array('quarantine','consumed','scrapped','recalled'),'quarantine'=>array('available','scrapped','recalled'),'recalled'=>array('quarantine','scrapped'),'consumed'=>array('recalled'),'scrapped'=>array());if(!isset($allowed[$lot['status']]) OR !in_array($status,$allowed[$lot['status']],TRUE))throw new Kohana_Exception('Недопустимый переход партии '.$lot['status'].' → '.$status);if(trim((string)$reason)==='')throw new Kohana_Exception('Укажите причину изменения статуса');
  DB::update('erp_412_lots')->set(array('status'=>$status,'updated_at'=>DB::expr('CURRENT_TIMESTAMP')))->where('id','=',(int)$lot['id'])->execute();$this->event($lot['id'],'status_changed',$lot['status'],$status,$reason,$reference_type,$reference_id,$actor);$updated=$this->get($lot['id']);$this->fact('erp412.lot.'.$status,$updated,$actor,array('reason'=>$reason));return $updated;
 }
 public function apply_quality_event($event,array $payload)
 {
  $inspection=(int)Arr::get($payload,'id');if(!$inspection)return;$links=DB::select('lot_id')->from('erp_412_quality_links')->where('inspection_id','=',$inspection)->execute()->as_array();foreach($links as $l){try{$lot=$this->get($l['lot_id']);if($event==='quarantined'&&$lot['status']==='available')$this->transition($lot['id'],'quarantine','Контроль '.$inspection,NULL,'erp405_inspection',$inspection);elseif($event==='released'&&$lot['status']==='quarantine')$this->transition($lot['id'],'available','Разрешено контролем '.$inspection,NULL,'erp405_inspection',$inspection);elseif($event==='scrapped'&&!in_array($lot['status'],array('scrapped','consumed'),TRUE))$this->transition($lot['id'],'scrapped','Списано контролем '.$inspection,NULL,'erp405_inspection',$inspection);}catch(Throwable $e){Kohana::$log->add(Log::ERROR,'erp412 quality hook: :error',array(':error'=>$e->getMessage()));}}
 }
 public static function on_stock_received(array $payload){self::instance()->auto_receive($payload);}public static function on_quality_quarantined(array $payload){self::instance()->apply_quality_event('quarantined',$payload);}public static function on_quality_released(array $payload){self::instance()->apply_quality_event('released',$payload);}public static function on_quality_scrapped(array $payload){self::instance()->apply_quality_event('scrapped',$payload);}
 public function auto_receive(array $payload){try{if(Arr::get($payload,'type')==='receipt')$this->from_movement((int)Arr::get($payload,'movement_id'));}catch(Throwable $e){Kohana::$log->add(Log::ERROR,'erp412 WMS hook: :error',array(':error'=>$e->getMessage()));}}
 public function get($id)
 {
  $where=Erp::is_uuid((string)$id)?'l.uuid':'l.id';$p=DB::query(Database::SELECT,"SELECT l.*,o.code item_code,o.name item_name,coalesce((SELECT sum(CASE WHEN a.direction IN('receipt','transfer_in','adjust_in') THEN a.qty ELSE -a.qty END) FROM erp_412_allocations a WHERE a.lot_id=l.id),0) qty_trace FROM erp_412_lots l LEFT JOIN erp_227_objects o ON o.id=l.item_id WHERE $where=:id")->param(':id',$id)->execute()->current();if(!$p)throw new Kohana_Exception('Партия не найдена');$p['balances']=$this->balances($p['id']);$p['quality']=DB::query(Database::SELECT,"SELECT q.*,i.number,i.status inspection_status,i.result,i.decision FROM erp_412_quality_links q LEFT JOIN erp_405_inspections i ON i.id=q.inspection_id WHERE q.lot_id=:id ORDER BY q.id DESC")->param(':id',(int)$p['id'])->execute()->as_array();return $p;
 }
 public function search(array $f=array(),$limit=50)
 {
  return DB::query(Database::SELECT,"SELECT l.id,l.uuid,l.lot_number,l.serial_number,l.item_id,l.status,l.expires_at,o.code item_code,o.name item_name,coalesce((SELECT sum(CASE WHEN a.direction IN('receipt','transfer_in','adjust_in') THEN a.qty ELSE -a.qty END) FROM erp_412_allocations a WHERE a.lot_id=l.id),0) qty_trace FROM erp_412_lots l LEFT JOIN erp_227_objects o ON o.id=l.item_id WHERE (:q='' OR l.lot_number ILIKE '%'||:q||'%' OR coalesce(l.serial_number,'') ILIKE '%'||:q||'%' OR o.code ILIKE '%'||:q||'%' OR o.name ILIKE '%'||:q||'%') AND (:status='' OR l.status=:status) AND (:item=0 OR l.item_id=:item) ORDER BY l.id DESC LIMIT :limit")->parameters(array(':q'=>trim((string)Arr::get($f,'q','')),':status'=>(string)Arr::get($f,'status',''),':item'=>(int)Arr::get($f,'item_id',0),':limit'=>max(1,min(200,(int)$limit))))->execute()->as_array();
 }
 public function genealogy($lot_id,$depth=20)
 {
  $lot=$this->get($lot_id);$depth=max(1,min(50,(int)$depth));$sql="WITH RECURSIVE graph AS (SELECT g.*,1 depth,ARRAY[g.input_lot_id,g.output_lot_id] path FROM erp_412_genealogy g WHERE g.input_lot_id=:id OR g.output_lot_id=:id UNION ALL SELECT g.*,x.depth+1,x.path||CASE WHEN g.input_lot_id=ANY(x.path) THEN g.output_lot_id ELSE g.input_lot_id END FROM graph x JOIN erp_412_genealogy g ON (g.input_lot_id=ANY(x.path) OR g.output_lot_id=ANY(x.path)) WHERE x.depth<:depth AND NOT(g.input_lot_id=ANY(x.path) AND g.output_lot_id=ANY(x.path))) SELECT DISTINCT ON(id) * FROM graph ORDER BY id,depth";$edges=DB::query(Database::SELECT,$sql)->parameters(array(':id'=>(int)$lot['id'],':depth'=>$depth))->execute()->as_array();$ids=array((int)$lot['id']);foreach($edges as $e){$ids[]=(int)$e['input_lot_id'];$ids[]=(int)$e['output_lot_id'];}$nodes=DB::select('id','uuid','lot_number','serial_number','item_id','status')->from('erp_412_lots')->where('id','IN',array_values(array_unique($ids)))->execute()->as_array();return array('root'=>$lot,'nodes'=>$nodes,'edges'=>$edges);
 }
 public function affected_outputs($lot_id){$lot=$this->get($lot_id);return DB::query(Database::SELECT,"WITH RECURSIVE d(id) AS (SELECT output_lot_id FROM erp_412_genealogy WHERE input_lot_id=:id UNION SELECT g.output_lot_id FROM erp_412_genealogy g JOIN d ON g.input_lot_id=d.id) SELECT l.id,l.uuid,l.lot_number,l.item_id,l.status,o.code item_code,o.name item_name FROM d JOIN erp_412_lots l ON l.id=d.id LEFT JOIN erp_227_objects o ON o.id=l.item_id ORDER BY l.id")->param(':id',(int)$lot['id'])->execute()->as_array();}
 public function balances($lot_id){return DB::query(Database::SELECT,"SELECT a.warehouse_id,w.code warehouse_code,w.name warehouse_name,sum(CASE WHEN direction IN('receipt','transfer_in','adjust_in') THEN qty ELSE -qty END) qty FROM erp_412_allocations a LEFT JOIN erp_401_warehouses w ON w.id=a.warehouse_id WHERE a.lot_id=:id GROUP BY a.warehouse_id,w.code,w.name HAVING sum(CASE WHEN a.direction IN('receipt','transfer_in','adjust_in') THEN a.qty ELSE -a.qty END)<>0 ORDER BY w.name")->param(':id',(int)$lot_id)->execute()->as_array();}
 protected function reachable($from,$target){return (bool)DB::query(Database::SELECT,"WITH RECURSIVE d(id) AS(SELECT output_lot_id FROM erp_412_genealogy WHERE input_lot_id=:from UNION SELECT g.output_lot_id FROM erp_412_genealogy g JOIN d ON g.input_lot_id=d.id) SELECT 1 found FROM d WHERE id=:target LIMIT 1")->parameters(array(':from'=>(int)$from,':target'=>(int)$target))->execute()->current();}
 protected function auto_quality_links(array $lot,array $movement,$actor)
 {
  $ids=array();
  if($movement['doc_type']==='erp403_receipt'&&$movement['doc_id'])$ids=DB::query(Database::SELECT,"SELECT i.id FROM erp_405_inspections i JOIN erp_403_receipt_lines l ON l.id=cast(i.source_ref AS integer) WHERE i.source='erp403_receipt' AND l.receipt_id=:doc AND l.item_id=:item")->parameters(array(':doc'=>(int)$movement['doc_id'],':item'=>(int)$movement['item_id']))->execute()->as_array(NULL,'id');
  elseif($movement['doc_type']==='erp402_order'&&$movement['doc_id'])$ids=DB::select('id')->from('erp_405_inspections')->where('source','=','erp402_order')->where('source_ref','=',(string)$movement['doc_id'])->where('item_id','=',(int)$movement['item_id'])->execute()->as_array(NULL,'id');
  foreach($ids as $id)$this->link_inspection($lot['id'],$id,$actor);
 }
 protected function movement($id){$m=DB::select()->from('erp_401_movements')->where('id','=',(int)$id)->where('status','=','posted')->execute()->current();if(!$m)throw new Kohana_Exception('Проведённое движение WMS не найдено');return $m;}
 protected function number(){$n=(int)DB::query(Database::SELECT,"SELECT nextval('erp_412_lot_number_seq') n")->execute()->get('n');return sprintf('LOT-%s-%06d',date('Ymd'),$n);}
 protected function event($lot,$type,$before,$after,$reason,$refType,$refId,$actor){DB::insert('erp_412_events',array('lot_id','event_type','before_status','after_status','reason','reference_type','reference_id','created_by'))->values(array((int)$lot,$type,$before,$after,$reason,$refType,$refId?:NULL,$actor?:NULL))->execute();}
 protected function fact($event,array $lot,$actor,array $extra=array()){$payload=array('lot_uuid'=>$lot['uuid'],'lot_number'=>$lot['lot_number'],'item_id'=>(int)$lot['item_id'],'status'=>$lot['status'],'actor_id'=>$actor)+$extra;if(class_exists('Service_Erp208_Outbox'))Service_Erp208_Outbox::instance()->enqueue($event,$payload,'erp412:'.$event.':'.$lot['uuid'].':'.hash('sha256',json_encode($payload)),array('aggregate_type'=>'lot','aggregate_id'=>$lot['uuid']));Event::fire($event,$payload,$actor);}
}
